  PRIMARY KEY (`id_registro`),
  KEY `id_produc` (`id_produc`),
  CONSTRAINT `registro_semanal_ibfk_1` FOREIGN KEY (`id_produc`) REFERENCES `producfo` (`id_produc`) ON DELETE CASCADE
